INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT1900000000000000000', '*', '', 'sec_doc19_official_exam_candidate', 'Fiche individuelle de candidat à un examen (DOC-19)', 'other', 'E', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["academic_year","class_name","exam_label","national_id","optional_subjects","pieces_block"]', NULL, '2026-11-07T02:01:00+01:00', '2026-11-07T02:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT19F0000000000000000', '*', '', 'sec_doc19_official_exam_candidate', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Fiche individuelle de candidat</h2><p>Examen : {{exam_label}} · Année scolaire : {{academic_year}}</p><p>Candidat : <strong>{{holder_name}}</strong>, classe {{class_name}}</p><p>Matricule : {{national_id}}</p><p>Matières facultatives : {{optional_subjects}}</p><p>Pièces du dossier :</p><pre>{{pieces_block}}</pre><p>Document interne de l’établissement, établi pour la constitution du dossier d’examen.</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p></body></html>', 1, '2026-11-07T02:01:00+01:00', NULL, '2026-11-07T02:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT19E0000000000000000', '*', '', 'sec_doc19_official_exam_candidate', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Candidate record</h2><p>Examination: {{exam_label}} · School year: {{academic_year}}</p><p>Candidate: <strong>{{holder_name}}</strong>, class {{class_name}}</p><p>National ID: {{national_id}}</p><p>Optional subjects: {{optional_subjects}}</p><p>File documents:</p><pre>{{pieces_block}}</pre><p>Internal school document, drawn up for the examination file.</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number: {{number}}</p></body></html>', 1, '2026-11-07T02:01:00+01:00', NULL, '2026-11-07T02:01:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT2000000000000000000', '*', '', 'sec_doc20_official_exam_candidate_list', 'Liste des candidats à un examen (DOC-20)', 'other', 'X', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["academic_year","class_name","exam_label","candidate_count","candidates_block"]', 'sec_chef_etablissement', '2026-11-07T02:01:00+01:00', '2026-11-07T02:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT20F0000000000000000', '*', '', 'sec_doc20_official_exam_candidate_list', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Liste des candidats</h2><p>Examen : {{exam_label}} · Année scolaire : {{academic_year}} · Classe : {{class_name}}</p><p>Nombre de candidats : {{candidate_count}}</p><pre>{{candidates_block}}</pre><p>Liste établie par {{holder_name}} à partir des inscriptions de la classe d’examen.</p><p>Le chef d’établissement</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p></body></html>', 1, '2026-11-07T02:01:00+01:00', NULL, '2026-11-07T02:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT20E0000000000000000', '*', '', 'sec_doc20_official_exam_candidate_list', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Candidate list</h2><p>Examination: {{exam_label}} · School year: {{academic_year}} · Class: {{class_name}}</p><p>Number of candidates: {{candidate_count}}</p><pre>{{candidates_block}}</pre><p>List drawn up by {{holder_name}} from the enrolments of the examination class.</p><p>The head of school</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number: {{number}}</p></body></html>', 1, '2026-11-07T02:01:00+01:00', NULL, '2026-11-07T02:01:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT3100000000000000000', '*', '', 'sec_doc31_official_exam_attestation', 'Attestation interne de résultat à un examen (DOC-31)', 'other', 'Q', '{CODE}-{AA}-{LETTRE}-{N6}', 1, 0, '["academic_year","class_name","exam_label","result_label"]', 'sec_chef_etablissement', '2026-11-07T02:01:00+01:00', '2026-11-07T02:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT31F0000000000000000', '*', '', 'sec_doc31_official_exam_attestation', 'fr', '<html><body><h1>{{establishment_name}}</h1><h2>Attestation interne de résultat</h2><p>Le chef d’établissement atteste que <strong>{{holder_name}}</strong>, élève de la classe {{class_name}} en {{academic_year}}, a été candidat à l’examen {{exam_label}}.</p><p>Résultat communiqué par l’organisateur : {{result_label}}</p><p>Cette attestation interne ne tient lieu ni de diplôme ni de relevé officiel.</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><div>{{qr}}</div><p>Numéro : {{number}}</p></body></html>', 1, '2026-11-07T02:01:00+01:00', NULL, '2026-11-07T02:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT31E0000000000000000', '*', '', 'sec_doc31_official_exam_attestation', 'en', '<html><body><h1>{{establishment_name}}</h1><h2>Internal examination result statement</h2><p>The head of school certifies that <strong>{{holder_name}}</strong>, a student of class {{class_name}} in {{academic_year}}, sat the {{exam_label}} examination.</p><p>Result reported by the organiser: {{result_label}}</p><p>This internal statement is neither a diploma nor an official transcript.</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><div>{{qr}}</div><p>Number: {{number}}</p></body></html>', 1, '2026-11-07T02:01:00+01:00', NULL, '2026-11-07T02:01:00+01:00');
